/* Все элементы делят пространство поровну */
.item { flex: 1; } /* = flex: 1 1 0% */

/* Первый элемент получает вдвое больше */
.item-1 { flex: 2; }
.item-2 { flex: 1; }
.item-3 { flex: 1; }

/* Элемент НЕ сжимается */
.item-no-shrink {
  flex-shrink: 0;
  width: 300px;
}

/* Элемент сжимается вдвое быстрее */
.item-fast-shrink {
  flex-shrink: 2;
}

/* flex-basis: 0% — все элементы от нуля, потом делят пространство */
.item { flex: 1; } /* = 1 1 0% */

/* flex-basis: auto — размер определяется содержимым */
.item { flex: 1; } /* = 1 1 auto — разный результат! */

/* flex-basis: фиксированный размер */
.sidebar { flex: 0 0 250px; }
.main { flex: 1; }

/* Решение 1: разрешить сжатие */
.item {
  min-width: 0;
  overflow: hidden;
}

/* Решение 2: не задавать ширину */
.item {
  flex: 1 1 0%; /* от нуля, не от содержимого */
}

/* Решение 3: ограничить */
.item {
  flex: 1 1 auto;
  max-width: 100%;
}

/* Элемент минимум 200px, даже если flex-shrink: 1 */
.item {
  flex: 1;
  min-width: 200px;
}

/* Элемент максимум 500px, даже если flex-grow: 3 */
.item {
  flex: 3;
  max-width: 500px;
}

/* Центрирование по обеим осям */
.container {
  display: flex;
  justify-content: center;
  align-items: center;
}

/* Тот же результат через auto margin */
.item {
  margin: auto;
}

/* Разнести элементы: один влево, другой вправо */
.item-left { margin-right: auto; }
.item-right { margin-left: auto; }

/* Один элемент внизу, остальные наверху */
.container {
  display: flex;
  align-items: flex-start;
  height: 300px;
}

.container .bottom-item {
  align-self: flex-end;
}

/* Выравнивание строк при переносе */
.container {
  flex-wrap: wrap;
  align-content: center; /* строки по центру */
}
